// Stock follows shocks to expected future integrated variance; factors fixed.
#include "asymmetric_readout.cpp"
// tables: each lag has [lo,step] and8193 pairs(C-convolved G_eta, derivative).
static double lookup_ge(int lag,double eta,const double*meta,const double*table){
 double lo=meta[2*lag],h=meta[2*lag+1],x=(eta-lo)/h;if(x>=8192)return 0.;if(x<0)return table[uint64_t(lag)*8193*2];int j=std::min(8191,int(x));double z=x-j;const double*v=table+(uint64_t(lag)*8193+j)*2;double delta=v[2]-v[0],c1=h*v[1],c2=3*delta-h*(2*v[1]+v[3]),c3=-2*delta+h*(v[1]+v[3]);return v[0]+z*(c1+z*(c2+z*c3));
}
extern "C" void forward_table(int nl,int nc,const double*sd,const double*nodes,const double*weights,const double*p,double*meta,double*table){
 for(int l=0;l<nl;++l){double lo=-8.,high=p[5]+std::abs(p[0]*sd[l]*nodes[0])+40/p[6],step=(high-lo)/8192;meta[2*l]=lo;meta[2*l+1]=step;for(int j=0;j<=8192;++j){double eta=lo+j*step,ge=0,gee=0;for(int c=0;c<nc;++c){double e=eta+p[0]*sd[l]*nodes[c],g=G(e,p),s=1/(1+std::exp(p[6]*(e-p[5])));ge+=weights[c]*2*g*s;gee+=weights[c]*g*(4*s*s-2*p[6]*s*(1-s));}double*o=table+(uint64_t(l)*8193+j)*2;o[0]=ge;o[1]=gee;}}
}
static void old_gradient(int l,int nq,double C,double Y,double F,const double*offset,const double*weight,const double*p,const double*meta,const double*table,double*out){
 out[0]=out[1]=out[2]=0;for(int j=0;j<nq;++j){const double*o=offset+(uint64_t(l)*nq+j)*2;double y=Y+o[0]-p[2],f=F+o[1]-p[4],eta=p[0]*C+p[1]*y*y+p[3]*f*f,ge=lookup_ge(l,eta,meta,table)*weight[j];out[0]+=p[0]*ge;out[1]+=2*p[1]*y*ge;out[2]+=2*p[3]*f*ge;}
}
static void future_loading(int nl,int nq,int nd,int ob,const double*state,double zs,double zf,const double*futuremean,const double*inverse_norm,const double*hat,const double*projection_lag,const double*diffusion_lag,const double*offset,const double*weight,const double*meta,const double*table,const double*lags,const double*p,const Model&m,double time,double*out){
 for(int j=0;j<ob+2;++j)out[j]=0;double qs=-std::expm1(-2*m.as*time),qf=-std::expm1(-2*m.af*time);
 for(int l=0;l<nl;++l){double mu[3]={futuremean[3*l],futuremean[3*l+1],futuremean[3*l+2]};for(int c=0;c<3;++c)for(int j=0;j<nd;++j)mu[c]+=projection_lag[(uint64_t(l)*3+c)*nd+j]*state[j];double grad[3];old_gradient(l,nq,mu[0],mu[1],mu[2],offset,weight,p,meta,table,grad);double factor=hat[l]*(1-m.w)*inverse_norm[l];for(int j=0;j<ob;++j)for(int c=0;c<3;++c)out[j]+=factor*grad[c]*diffusion_lag[(uint64_t(l)*3+c)*ob+j];double ds=std::exp(-m.as*lags[l]),df=std::exp(-m.af*lags[l]),As=std::exp(m.bs*ds*zs-.5*m.bs*m.bs*ds*ds*qs),Af=std::exp(m.bf*df*zf-.5*m.bf*m.bf*df*df*qf);out[ob]+=hat[l]*m.w*(1-m.r)*m.bs*ds*std::sqrt(2*m.as)*As;out[ob+1]+=hat[l]*m.w*m.r*m.bf*df*std::sqrt(2*m.af)*Af;}
}
extern "C" void forward_probe(int n,int nl,int nq,int nd,int ob,const double*states,const double*stress,const double*futuremean,const double*inverse_norm,const double*hat,const double*projection_lag,const double*diffusion_lag,const double*offset,const double*weight,const double*meta,const double*table,const double*lags,const double*p,const double*x,double time,double*out){Model m(x);for(int i=0;i<n;++i)future_loading(nl,nq,nd,ob,states+uint64_t(i)*nd,stress[2*i],stress[2*i+1],futuremean,inverse_norm,hat,projection_lag,diffusion_lag,offset,weight,meta,table,lags,p,m,time,out+uint64_t(i)*(ob+2));}
extern "C" void forward_stock(int nt,int pairs,int stride,int nd,int ob,int ne,int nl,int nq,const int*tr,const double*dec,const double*root,const double*cross,const double*bmean,const double*broot,const double*diffusion,const double*mean,const double*proj,const double*time,const double*dt,const int*seg,const int*coarse,const int*reference,const int*expiry,const int*update,const double*norm,const double*p,const double*x,const double*futuremean,const double*inverse_norm,const double*hat,const double*projection_lag,const double*diffusion_lag,const double*offset,const double*weight,const double*meta,const double*table,const double*lags,uint64_t seed,double*out){
 Model m(x);int nb=ob+2;std::vector<double>ds(nt),df(nt),ns(nt),nf(nt),cs(nt),cf(nt),rs(nt),rf(nt),qs(nt),qf(nt);for(int t=0;t<nt;++t){double h=dt[t];ds[t]=std::exp(-m.as*h);df[t]=std::exp(-m.af*h);ns[t]=std::sqrt(-std::expm1(-2*m.as*h));nf[t]=std::sqrt(-std::expm1(-2*m.af*h));rs[t]=std::sqrt(residual(m.as,h));rf[t]=std::sqrt(residual(m.af,h));cs[t]=std::sqrt(h-rs[t]*rs[t]);cf[t]=std::sqrt(h-rf[t]*rf[t]);qs[t]=-std::expm1(-2*m.as*time[t]);qf[t]=-std::expm1(-2*m.af*time[t]);}
 auto worker=[&](int begin,int end){for(int i=begin;i<end;++i){std::vector<double>s(nd,0),next(nd),z(nd+1),extra(ob-1),db(nb),instant(nb),heldinstant(2*nb),future(4*nb),state(nd),K(nb);double zs=0,zf=0,logs[2][4][2]={},refv[2]={},reflog[2]={},hold[2]={};
 for(int t=0;t<nt;++t){int transition=tr[t];uint64_t pathstep=uint64_t(t)*stride+i,k=pathstep*(nd+3);for(int j=0;j<nd+1;++j)z[j]=gaussian(seed,k+j);double dw=std::sqrt(dt[t])*z[0],es=gaussian(seed,k+nd+1),ef=gaussian(seed,k+nd+2);db[0]=dw;db[ob]=cs[t]*es+rs[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*pathstep);db[ob+1]=cf[t]*ef+rf[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*pathstep+1);for(int j=0;j<ob-1;++j)extra[j]=gaussian(seed^UINT64_C(0x78d904ef6038fb35),pathstep*(ob-1)+j);const double*bm=bmean+uint64_t(transition)*(ob-1)*nd,*br=broot+uint64_t(transition)*(ob-1)*(ob-1);for(int j=0;j<ob-1;++j){double v=0;for(int l=0;l<nd;++l)v+=bm[j*nd+l]*z[l+1];for(int l=0;l<ob-1;++l)v+=br[j*(ob-1)+l]*extra[l];db[j+1]=v;}
 double fixedshock=.6*dw-.8*(std::sqrt(1-m.r)*db[ob]+std::sqrt(m.r)*db[ob+1]),pr[3]={};for(int j=0;j<nd;++j)for(int c=0;c<3;++c)pr[c]+=proj[c*nd+j]*s[j];
 for(int anti=0;anti<2;++anti){double sign=anti?-1:1,C=mean[3*t]+sign*pr[0],Y=mean[3*t+1]+sign*pr[1],F=mean[3*t+2]+sign*pr[2],eta=p[0]*C+p[1]*std::pow(Y-p[2],2)+p[3]*std::pow(F-p[4],2),R=G(eta,p)*std::exp(-norm[t]),As=std::exp(sign*m.bs*zs-.5*m.bs*m.bs*qs[t]),Af=std::exp(sign*m.bf*zf-.5*m.bf*m.bf*qf[t]),A=(1-m.r)*As+m.r*Af,H=(1-m.w)*R+m.w*A,v=m.f+(.2-m.f)*x[seg[t]]*H,sig=1/(1+std::exp(p[6]*(eta-p[5]))),g[3]={p[0],2*p[1]*(Y-p[2]),2*p[3]*(F-p[4])},length=0;
 for(int j=0;j<nb;++j){double value=0;if(j<ob){for(int c=0;c<3;++c)value+=2*(1-m.w)*R*sig*g[c]*diffusion[c*ob+j];}else if(j==ob)value=m.w*(1-m.r)*m.bs*std::sqrt(2*m.as)*As;else value=m.w*m.r*m.bf*std::sqrt(2*m.af)*Af;instant[j]=-value;length+=value*value;}length=std::sqrt(length);for(double&value:instant)value/=length;
 if(coarse[t]){hold[anti]=v;for(int j=0;j<nb;++j)heldinstant[anti*nb+j]=instant[j];}
 if(update[t]>=0){int u=update[t];for(int j=0;j<nd;++j)state[j]=sign*s[j];future_loading(nl,nq,nd,ob,state.data(),sign*zs,sign*zf,futuremean+uint64_t(u)*nl*3,inverse_norm+uint64_t(u)*nl,hat+uint64_t(u)*nl,projection_lag,diffusion_lag,offset,weight,meta,table,lags,p,m,time[t],K.data());double normK=0;for(double value:K)normK+=value*value;normK=std::sqrt(normK);for(int j=0;j<nb;++j){double value=normK>1e-100?-K[j]/normK:(j==0?.6:j==ob?-.8*std::sqrt(1-m.r):j==ob+1?-.8*std::sqrt(m.r):0);future[(anti*2+1)*nb+j]=value;if(u%2==0)future[(anti*2)*nb+j]=value;}}
 for(int grid=0;grid<2;++grid){double shocks[4]={fixedshock,0,0,0};for(int j=0;j<nb;++j){shocks[1]+=(grid?instant[j]:heldinstant[anti*nb+j])*db[j];shocks[2]+=future[(anti*2)*nb+j]*db[j];shocks[3]+=future[(anti*2+1)*nb+j]*db[j];}double vv=grid?v:hold[anti];for(int model=0;model<4;++model)logs[anti][model][grid]+=-.5*vv*dt[t]+std::sqrt(vv)*sign*shocks[model];}
 if(reference[t])refv[anti]=m.f+(.2-m.f)*x[seg[t]]*((1-m.w)+m.w*A);reflog[anti]+=-.5*refv[anti]*dt[t]+std::sqrt(refv[anti])*sign*fixedshock;if(expiry[t]>=0){double*o=out+((uint64_t(anti*pairs+i)*ne+expiry[t])*10);for(int model=0;model<4;++model)for(int grid=0;grid<2;++grid)o[2*model+grid]=std::exp(logs[anti][model][grid]);o[8]=o[9]=std::exp(reflog[anti]);}
 }
 const double*r=root+uint64_t(transition)*nd*nd;for(int j=0;j<nd;++j){double v=cross[transition*nd+j]*dw;for(int l=0;l<nd;++l)v+=r[j*nd+l]*z[l+1];next[j]=dec[transition*nd+j]*s[j]+v;}s.swap(next);zs=ds[t]*zs+ns[t]*es;zf=df[t]*zf+nf[t]*ef;
 }}};std::vector<std::thread>threads;for(int j=0;j<4;++j)threads.emplace_back(worker,pairs*j/4,pairs*(j+1)/4);for(auto&t:threads)t.join();
}
